# 4. The competitor insight and the innovation read
# ---------------------------------------------------------------------

def _insight_context():
    return {"subcategory_analysis": None, "competitor_count": 7, "industry_type": "Food and Beverage",
            "location": "Tibag", "forecast": None}


def test_one_invented_sentence_does_not_cost_the_whole_insight():
    rule = rec_service.competitor_insight_from(None, 7, "Food and Beverage", "Tibag", None)
    llm = {"short": "7 food businesses trade here. Most earn ₱90,000 a day.",
           "detail": "There are 7 of them in Tibag. A clear niche wins. Sadly 90% of them close within a year."}
    chosen = rec_service._choose_competitor_insight(llm, "llm:gemini:x", rule, _insight_context())
    assert chosen["generated_by"] == "llm:gemini:x"
    assert chosen["short"] == "7 food businesses trade here."
    assert chosen["detail"] == "There are 7 of them in Tibag. A clear niche wins."


def test_a_plan_with_no_idea_gets_gemini_s_suggestions_unrated():
    assert llm_service._coerce_innovation({"summary": "Stand out.", "suggestions": ["a"]}) == \
        {"novelty": None, "summary": "Stand out.", "suggestions": ["a"]}
    assert llm_service._coerce_innovation({"novelty": "Huge", "summary": "x"}) is None
    assert llm_service._coerce_innovation({"suggestions": ["a"]}) is None


def test_the_prompt_asks_for_suggestions_when_there_is_no_idea(app):
    context = {"subcategory_label": None, "subcategory": None, "product_offering": "", "offering_items": [],
               "subcategory_analysis": None, "innovation_idea": "", "industry_type": "Retail",
               "location": "Tibag"}
    with app.app_context():
        prompt = llm_service._plan_detail_prompt(context)
    assert "has not said yet what makes the business different" in prompt
    assert '"innovation"' in prompt and '"suggestions"' in prompt


# ---------------------------------------------------------------------
# 5. The page script
# ---------------------------------------------------------------------

def test_the_script_repaints_and_asks_again_by_itself():
    with open(os.path.join(ROOT, "app", "static", "js", "forecast_transcript.js"), encoding="utf-8") as f:
        script = f.read()
    assert "new DOMParser().parseFromString" in script and "data-ai-region" in script
    assert "region.replaceWith(document.importNode(replacement, true))" in script
    assert re.search(r"const MAX_ROUNDS = \d+;", script)
    assert "data.retry_after" in script and "window.setTimeout" in script
    assert "innerHTML" not in script.split("function showTranscript", 1)[1].split("function successMessage", 1)[0] \
        .replace("template.innerHTML", ""), "model text is never parsed as HTML"
